def get_resource_url(region, hash, type):
    url_template = "{}://{}-s2-depot.{}/{}.{}"
    scheme = "https"
    domain = "classic.blizzard.com"

    if region == "sea":
        region = "us"
    elif region == "cn":
        domain = "necdn.leihuo.netease.com"
    return url_template.format(scheme, region, domain, hash, type)
